'X':np.array(list(map(int,'111010010'))),
'H':np.array(list(map(int,'110011101'))),
}
def eca(a,rule,wrap=False,bound=0,rev=False):
 out=[];n=len(a)
 for i in range(n):
  l=a[(i-1)%n] if wrap or i>0 else bound
  c=a[i]
  r=a[(i+1)%n] if wrap or i<n-1 else bound
  idx=(l<<2)|(c<<1)|r
  out.append((rule>>idx)&1)
 return np.array(out)
for wrap in [False,True]:
 for bound in [0,1]:
  sols=[]
  for rule in range(256):
   if np.array_equal(eca(seqs['A'],rule,wrap,bound),seqs['T']) and np.array_equal(eca(seqs['G'],rule,wrap,bound),seqs['X']):sols.append(rule)
  print('wrap',wrap,'bound',bound,'left sols',sols)
# rows independently ECA length3, cols etc search
for axis in [0,1]:
 for wrap in [False,True]:
  for bound in [0,1]:
   sols=[]
   for rule in range(256):
